'use client'; import {ChangeEvent} from 'react'; import {useStylingFlow} from '../use-styling-flow';
export function PhotoPicker(){const {previewUrl,selectPhoto}=useStylingFlow();const pick=(e:ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(f)selectPhoto(f)};return <label className="mt-8 flex aspect-[3/4] items-center justify-center overflow-hidden rounded-3xl border-2 border-dashed border-zinc-200 bg-zinc-50">{previewUrl?<img src={previewUrl} className="h-full w-full object-cover" alt="업로드 미리보기"/>:<span className="text-zinc-400">사진 선택하기</span>}<input className="hidden" type="file" accept="image/*" onChange={pick}/></label>}